import "server-only";

/* ===========================================================================
 *  THE ONLY FILE THAT TALKS TO DJANGO
 *
 *  Everything above it — resource modules, React Query hooks, every page and
 *  component — is written against this client and never touches `fetch`.
 * ======================================================================== */

export async function request<T>(schema: ZodType<T>, options: RequestOptions): Promise<T> {
  const payload = await httpRequest(options);

  const parsed = schema.safeParse(payload);
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    // A serializer that drifted from the contract fails loudly *here*,
    // rather than rendering blanks three components deep.
    throw new ApiError(
      502,
      `${options.method ?? "GET"} ${options.path} returned an unexpected shape: ` +
        `${issue.path.join(".") || "(root)"} — ${issue.message}`,
    );
  }
  return parsed.data;
}

class OptimisticLockMixin:
    """Refuse a write that was composed against a stale copy of the object."""

    lock_field = "updated_at"

    def perform_update(self, serializer):
        expected = self.request.data.get("expected_updated_at")
        if expected:
            current = getattr(serializer.instance, self.lock_field, None)
            if current is not None and _to_iso(current) != _normalise(expected):
                raise Conflict()
        serializer.save()

