@shared_task(bind=True, **RETRY_POLICY)
def index_object(self, kind, pk):
    """(Re)build the embedding for a single object."""
    obj = _model_for(kind).objects.filter(pk=pk).first()
    if obj is None:
        logger.info("index_object: %s:%s no longer exists, skipping", kind, pk)
        return

    is_blog = kind == C.KIND_BLOG

    # A save that touched nothing the embedding is built from does not need a
    # (billed) round trip to Gemini.
    if is_blog and unchanged_since_last_index(obj):
        logger.info("index_object: blog:%s text unchanged, skipping re-embed", pk)
        return

    try:
        digest = SearchService.index_object(kind, obj)
    except PermanentError as exc:
        # Will fail identically every time — record it and stop, rather than
        # spending the full retry budget on it.
        if is_blog:
            record_failure(pk, exc)
        return
    except Exception as exc:
        if is_blog:
            record_failure(pk, exc)
        raise  # TransientError — the retry policy takes it from here

    if is_blog:
        record_success(pk, digest)

# gemini-embedding-001 is trained for asymmetric retrieval: the *query* gets an
# instruction prefix, while indexed *documents* stay plain. This markedly
# improves relevance, especially for short queries.
_QUERY_INSTRUCTION = (
    "Instruct: Given a search query, retrieve relevant blog posts, playlists "
    "and author profiles that match it.\nQuery: "
)


class InstructedGeminiEmbeddings(GoogleGenerativeAIEmbeddings):
    def embed_query(self, text: str) -> List[float]:
        return super().embed_query(f"{_QUERY_INSTRUCTION}{text}")

class TransientError(Exception):
    """Upstream was unavailable, rate-limited, or timed out. Retry."""


class PermanentError(Exception):
    """The input cannot produce a result. Do not retry."""


# Spread as **RETRY_POLICY into @shared_task.
RETRY_POLICY = {
    "autoretry_for": (TransientError,),
    "retry_backoff": 2,          # 2s, 4s, 8s, ...
    "retry_backoff_max": 300,
    "retry_jitter": True,        # avoid a thundering herd after an outage
    "max_retries": 5,
}

def cache_key(family: str, *parts) -> str:
    suffix = ':'.join(str(part) for part in parts)
    key = f"{family}:v{version(family)}"
    return f"{key}:{suffix}" if suffix else key


def bump(family: str) -> None:
    """Invalidate every key in `family`."""
    try:
        cache.incr(_version_key(family))
    except ValueError:
        # Nothing cached yet, so there is nothing to invalidate.
        cache.set(_version_key(family), 1, VERSION_TTL)


